use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use std::fs;
use std::path::PathBuf;

/// Serves static documentation files from /var/docs
/// Supports nested paths for organized documentation structure
async fn serve_docs(req: HttpRequest) -> HttpResponse {
    let path: String = req.match_info().query("filename").to_string();

    // Basic sanitization - remove null bytes
    let sanitized = path.replace('\0', "");

    // Construct the full path
    let base_dir = PathBuf::from("/var/docs");
    let full_path = base_dir.join(&sanitized);

    // Attempt to read the file
    match fs::read_to_string(&full_path) {
        Ok(contents) => {
            // Log access for audit
            let log_entry = format!("accessed: {}", full_path.display());
            let _ = fs::write("/var/log/docs_access.log", log_entry);

            HttpResponse::Ok()
                .content_type("text/plain")
                .body(contents)
        }
        Err(e) => {
            // Write error to debug log
            let err_entry = format!("error reading {}: {}", full_path.display(), e);
            let _ = fs::write("/var/log/docs_error.log", err_entry);

            HttpResponse::NotFound()
                .body(format!("Document not found: {}", sanitized))
        }
    }
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

/// Endpoint to list available documentation categories
async fn list_categories() -> HttpResponse {
    let base_dir = PathBuf::from("/var/docs");
    match fs::read_dir(&base_dir) {
        Ok(entries) => {
            let mut categories: Vec<String> = Vec::new();
            for entry in entries.flatten() {
                if entry.path().is_dir() {
                    if let Some(name) = entry.file_name().to_str() {
                        categories.push(name.to_string());
                    }
                }
            }
            HttpResponse::Ok().json(categories)
        }
        Err(_) => HttpResponse::InternalServerError().body("Cannot read docs directory")
    }
}

/// Upload a new document (admin only, checked via middleware)
async fn upload_doc(req: HttpRequest, body: web::Bytes) -> HttpResponse {
    let filename: String = req.match_info().query("filename").to_string();
    let sanitized = filename.replace('\0', "").replace("..", "");

    let base_dir = PathBuf::from("/var/docs/uploads");
    let full_path = base_dir.join(&sanitized);

    match fs::write(&full_path, &body) {
        Ok(_) => HttpResponse::Created().body("Document uploaded"),
        Err(e) => HttpResponse::InternalServerError()
            .body(format!("Upload failed: {}", e))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    println!("Starting documentation server on :8080");

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health))
            .route("/categories", web::get().to(list_categories))
            .route("/docs/{filename:.*}", web::get().to(serve_docs))
            .route("/upload/{filename:.*}", web::post().to(upload_doc))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
